    g.setAttribute('position', new THREE.Float32BufferAttribute([-1, -1, 0, 1, -1, 0, 1, 1, 0, -1, 1, 0], 3));
    g.setIndex([0, 1, 2, 0, 2, 3]);
    g.setAttribute('aLobe', new THREE.InstancedBufferAttribute(new Float32Array(lobes), 4));
    g.setAttribute('aTone', new THREE.InstancedBufferAttribute(new Float32Array(tone), 3));
    g.instanceCount = lobes.length / 4;
    console.info('[m07cloud]', name, 'lobes', g.instanceCount);
    const m = new THREE.ShaderMaterial({
      vertexShader: CLOUD_VERT, fragmentShader: CLOUD_FRAG, fog: false, side: THREE.DoubleSide,
      uniforms: { uGuard: shared.uGuard, uProjPos: shared.uProjPos, uClip: shared.uClip, uPjPost: shared.uPjPost, uPjRes: shared.uPjRes, uMagOn: { value: magOn }, uCScale: { value: sc } },
    });
