   * r22 m07cloud: one painted cumulus mound beyond the band edge on one side (side = ±1), centred at along a; place(lat, along, up)
   * → group-local. Built like the painted foam: 2–4 big domes sunk into the water, softer lobes heaped on top of them, and many
   * small bumps half out of every big lobe (the lumpy cauliflower outline), a few loose bubbles at the river edge. Mound size and
   * spacing vary (no row of equal balls).
   */
  type Place = (lat: number, a: number, up: number) => THREE.Vector3;
  const edge = 2.95;
  const pushL = (out: number[], tone: number[], place: Place, side: number, wallLat: number, lat: number, along: number, up: number, r: number, lvl: number) => {
    lat = Math.max(lat, edge - r * 0.35);
    if (lat + r * 0.25 > wallLat) lat = wallLat - r * 0.25;
    const p = place(side * lat, along, up);
    out.push(p.x, p.y, p.z, r); tone.push(rnd(), rnd(), lvl);
  };
