  let swB = 0; // r24 m07swing: 1 while the drop's bank is built (mound size follows the room between the band and the wall)
  const mound = (out: number[], tone: number[], place: Place, side: number, a: number, wallLat: number, S: number, inset = 0) => {
    if (low > 0) S *= lowK;
    if (swB > 0) S *= THREE.MathUtils.clamp(0.25 + (0.75 * (wallLat - edge - inset)) / 1.9, 0.3, 1.3);

